namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public List<int> Ratings { get; set; } = [];

    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
            Ingredients = "2 cups flour\n2 eggs\n1 cup milk\n2 tbsp sugar\n1 tsp baking powder",
            Steps = "1. Mix dry ingredients.\n2. Whisk eggs and milk together.\n3. Combine wet and dry.\n4. Cook on griddle until golden.",
            Ratings = [4, 5, 4]
        },
        new()
        {
            Id = 2, Title = "Spaghetti Bolognese", Category = "Dinner",
            Ingredients = "400g spaghetti\n500g ground beef\n1 can crushed tomatoes\n1 onion\n3 cloves garlic",
            Steps = "1. Cook spaghetti al dente.\n2. Sauté onion and garlic.\n3. Brown beef.\n4. Add tomatoes and simmer 20 min.\n5. Serve over pasta.",
            Ratings = [5, 5, 4, 5]
        },
        new()
        {
            Id = 3, Title = "Caesar Salad", Category = "Lunch",
            Ingredients = "1 head romaine lettuce\nCaesar dressing\nCroutons\nParmesan cheese",
            Steps = "1. Chop lettuce.\n2. Toss with dressing.\n3. Top with croutons and parmesan.",
            Ratings = [3, 4]
        },
        new()
        {
            Id = 4, Title = "Chocolate Chip Cookies", Category = "Desserts",
            Ingredients = "2¼ cups flour\n1 cup butter\n¾ cup sugar\n2 eggs\n2 cups chocolate chips",
            Steps = "1. Cream butter and sugar.\n2. Add eggs.\n3. Mix in flour.\n4. Fold in chocolate chips.\n5. Bake at 375°F for 10 min.",
            Ratings = [5, 5, 5]
        },
        new()
        {
            Id = 5, Title = "Avocado Toast", Category = "Breakfast",
            Ingredients = "2 slices bread\n1 ripe avocado\nSalt and pepper\nRed pepper flakes\nLemon juice",
            Steps = "1. Toast bread.\n2. Mash avocado with lemon juice, salt, pepper.\n3. Spread on toast.\n4. Sprinkle red pepper flakes.",
            Ratings = [4, 4, 5]
        },
        new()
        {
            Id = 6, Title = "Grilled Chicken Wrap", Category = "Lunch",
            Ingredients = "2 chicken breasts\nTortillas\nLettuce\nTomato\nRanch dressing",
            Steps = "1. Grill chicken until cooked through.\n2. Slice chicken.\n3. Assemble wraps with toppings.\n4. Drizzle with ranch.",
            Ratings = [4, 3, 4]
        }
    ];

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.Ratings.Add(stars);
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Count > 0 ? _recipes.Max(r => r.Id) + 1 : 1;
        _recipes.Add(recipe);
    }
}

